const CATEGORY_MODEL={rail:'braking',automotive:'braking',water:'hydro',marine:'hydro',environment:'hydro',semiconductor:'thermal',packaging:'thermal',manufacturing:'thermal',electronics:'circuit',computing:'compute',structures:'elastic',underground:'elastic',materials:'elastic',aerospace:'drag',space:'optics',instruments:'optics',megascience:'optics',biomedical:'microflow',energy:'heating',process:'heating'};
export function sceneModelFor(course={}){return CATEGORY_MODEL[course.category]||'thermal';}
export function sceneDefaults(kind){const model=SCENE_MODELS[kind];if(!model)throw new RangeError('Unknown scene model');return Object.fromEntries(model.params.map(p=>[p.id,p.value]));}
export function calculateSceneModel(kind,values){
 const model=SCENE_MODELS[kind];if(!model)throw new RangeError('Unknown scene model');
 for(const p of model.params)if(!Number.isFinite(values[p.id])||values[p.id]<p.min-1e-9||values[p.id]>p.max+1e-9)throw new RangeError(p.id+' outside teaching range');
 let value,detail;
 if(kind==='braking'){const v=values.speed/3.6,reaction=v*values.reaction,braking=v*v/(2*values.deceleration);value=reaction+braking;detail={reactionDistance:reaction,brakingDistance:braking,stoppingTime:values.reaction+v/values.deceleration};}
 if(kind==='hydro'){value=9.81*values.flow*values.head*values.efficiency;detail={hydraulicPower:9.81*values.flow*values.head};}
 if(kind==='thermal'){const tau=values.resistance*20;value=values.power*values.resistance*(-Math.expm1(-values.time/tau));detail={timeConstant:tau,steadyRise:values.power*values.resistance};}
 if(kind==='circuit'){value=values.voltage**2/values.resistance;detail={current:values.voltage/values.resistance};}
 if(kind==='compute'){const transfer=8*values.size/values.bandwidth;value=transfer+values.compute/1000;detail={transferTime:transfer,computeTime:values.compute/1000};}
 if(kind==='elastic'){value=values.force*1000/values.area;detail={microstrain:value/200000*1e6};}
 if(kind==='drag'){value=.5*1.225*values.speed**2*values.coefficient*values.area;detail={dragPower:value*values.speed};}
 if(kind==='optics'){value=299792.458/values.wavelength;detail={photonEnergyEv:1239.841984/values.wavelength};}
 if(kind==='microflow'){const r=values.radius*1e-6,L=values.length*.001,Q=Math.PI*values.pressure*r**4/(8*.001*L),v=Q/(Math.PI*r*r),Re=1000*v*2*r/.001;value=Q*6e10;detail={reynolds:Re,meanVelocity:v};if(Re>=2000)throw new RangeError('Laminar regime exceeded');}
 if(kind==='heating'){value=values.power*values.time/(values.mass*4180);detail={energy:values.power*values.time};}
 if(!Number.isFinite(value))throw new RangeError('Non-finite teaching result');
 return {kind,value,unit:model.unit,detail};
}

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localUrl=value=>typeof value==='string'&&/^(?:\.\/)?assets\/[A-Za-z0-9_./-]+$/.test(value)&&!value.split('/').includes('..')?value:'';
const externalUrl=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:'';}catch{return '';}};
const text=(value,en)=>Array.isArray(value)?value[en?1:0]:String(value??'');
const title=(object,en,key='title')=>object?.[en?key+'En':key]||object?.[key]||'';
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
const number=v=>new Intl.NumberFormat('en',{maximumSignificantDigits:5}).format(v);
export function projectArchitecture(course={}){
 const architecture=course.v16Architecture||course,authored=Array.isArray(architecture.architectureNodes)&&architecture.architectureNodes.length>0;
 const raw=authored?architecture.architectureNodes:course.stages||[];
 const nodes=raw.map((node,index)=>{
  const p=Array.isArray(node)?{title:node[0],titleEn:node[1]}:typeof node==='string'?{title:node}:node||{};
  return {id:String(p.id??index),index,title:String(p.title||p.label||p.name||''),titleEn:String(p.titleEn||p.labelEn||p.nameEn||p.title||p.label||p.name||''),role:String(p.role||p.description||''),roleEn:String(p.roleEn||p.descriptionEn||p.role||p.description||''),sourceIds:Array.isArray(p.sourceIds)?p.sourceIds.filter(x=>typeof x==='string'):[]};
 }).filter(n=>n.title||n.titleEn);
 if(!nodes.length)return null;
 const at=value=>Number.isInteger(value)?nodes.find(n=>n.index===value):nodes.find(n=>n.id===String(value));
 const rawEdges=authored?architecture.architectureEdges||[]:nodes.slice(1).map((n,i)=>[nodes[i].index,n.index]);
 const edges=rawEdges.map(edge=>{const a=at(Array.isArray(edge)?edge[0]:edge?.source??edge?.from),b=at(Array.isArray(edge)?edge[1]:edge?.target??edge?.to);return a&&b&&a!==b?{from:a.id,to:b.id,label:Array.isArray(edge)?'':String(edge.label||''),labelEn:Array.isArray(edge)?'':String(edge.labelEn||edge.label||'')}:null;}).filter(Boolean);
 return {kind:authored?'architecture':'stages',nodes,edges,sourceIds:Array.isArray(course.sourceIds)?course.sourceIds.filter(x=>typeof x==='string'):[]};
}
function renderProjectArchitecture(course,en){
 const data=projectArchitecture(course);if(!data)return '';const t=(zh,english)=>en?english:zh;
 return `<details class="iv16-project-map" open><summary>${data.kind==='architecture'?t('這項工程如何組成','How this project fits together'):t('這項工程的學習階段','Learning stages of this project')} <span>${data.nodes.length} ${t('個可探索節點','explorable nodes')}</span></summary><p class="iv16-map-intro">${data.kind==='architecture'?t('點選本專題的元件或工序節點，查看教材提供的角色、連結與來源。連線是課程概念關係，不是照片內設備的實際配置或控制接線。','Select a project component or process node to inspect its supplied role, connections and sources. Lines show curriculum relationships, not equipment positions or control wiring in the photograph.'):t('節點使用本課程的階段名稱；箭頭只表示學習順序。','Nodes use this course’s stage names; arrows indicate learning order only.')}</p><div class="iv16-architecture"><svg aria-hidden="true"></svg><div class="iv16-project-nodes">${data.nodes.map((node,i)=>`<button type="button" data-scene-node="${esc(node.id)}" aria-pressed="false"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(title(node,en))}</strong></button>`).join('')}</div></div><div class="iv16-node-detail"><div><span class="iv16-eyebrow">${t('專題節點','PROJECT NODE')}</span><h3 data-scene-node-title>${t('點選一個節點開始','Select a node to begin')}</h3><p data-scene-node-role>${t('此區使用專題本身的教材資訊，下方暖身實驗另採領域的簡化模型。','This panel uses project-specific curriculum information; the warm-up experiment below uses a separate simplified domain model.')}</p></div><div><strong class="iv16-node-subhead">${t('相連節點','Connected nodes')}</strong><div data-scene-node-links></div></div><div><strong class="iv16-node-subhead" data-scene-source-label>${t('本課程來源','Course sources')}</strong><ul data-scene-node-sources></ul></div></div></details>`;
}
export function resolveScenePhoto(course={},photos=[],manifest=null){
 const list=manifest?.photos||photos||[],entry=manifest?.courses?.[course.id];
 const categoryEntry=manifest?.categories?.[course.category];
 const ids=[...(entry?.photoIds||[]),entry?.photoId,course.photoId,typeof categoryEntry==='string'?categoryEntry:categoryEntry?.photoId].filter(Boolean);
 let photo=ids.map(id=>list.find(p=>p.id===id)).find(p=>p&&localUrl(p.path));
 if(!photo)photo=list.find(p=>p.courseIds?.includes(course.id)&&localUrl(p.path))||list.find(p=>p.categories?.includes(course.category)&&localUrl(p.path));
 if(!photo)return null;
 const exact=entry?.match==='exact'&&(entry.photoIds?.includes(photo.id)||entry.photoId===photo.id);
 return {photo,match:exact?'exact':'representative',note:entry?.note||categoryEntry?.note||'代表性工程照片；不代表本課程工程的實際設備配置。',noteEn:entry?.noteEn||categoryEntry?.noteEn||'Representative engineering photograph; not the actual equipment layout of this project.'};
}

